const sha = value => crypto.createHash('sha256').update(value).digest('hex');
function uuid(content) {
  const h = sha(content);
  return h.slice(0,8)+'-'+h.slice(8,12)+'-5'+h.slice(13,16)+'-8'+h.slice(17,20)+'-'+h.slice(20,32);
